globalThis.CONV_DATA = {"H": 64, "W": 64, "C": 3, "R": 5, "S": 5, "M": 32, "P": 60, "Q": 60, "input": "", "weights": "", "bias": "g7wHPBNI+jtvcvG7taH2PKXOKjsvRU09mmTtvK346TyWaTo9V4EpvZ3WrTyzIyc8xbKKPVhoLDxFbAs9fj2qPLqK0DwjwJk6IMe6vHdHT7zi9kw8dQTxvHOx1jyuJqo7Jo8EvKKPQTugJi23K/tVvAnN5zwD6cc9Pk2bu12Sar0=", "reference": "", "cppReference": "", "sources": [{"key": "lab2", "title": "Lab 2 · 실제 convolution", "path": "cpre487lab2/src/layers/Convolutional.cpp", "start": 13, "code": "void ConvolutionalLayer::computeNaive(const LayerData& dataIn) const {\n    // Dimensions, named as in the textbook: input (H, W, C), weights (R, S, C, M), output (P, Q, M)\n    const dimVec& inDims = getInputParams().dims;\n    const dimVec& outDims = getOutputParams().dims;\n    const dimVec& weightDims = getWeightParams().dims;\n\n    const size W = inDims[1], C = inDims[2];\n    const size P = outDims[0], Q = outDims[1], M = outDims[2];\n    const size R = weightDims[0], S = weightDims[1];\n\n    LayerData& dataOut = getOutputData();\n\n    // Stride 1, no padding: output (p, q) covers input rows p..p+R-1 and columns q..q+S-1\n    for (size p = 0; p < P; p++) {\n        for (size q = 0; q < Q; q++) {\n            for (size m = 0; m < M; m++) {\n                fp32 sum = biasData.get<fp32>(m);\n\n                for (size r = 0; r < R; r++) {\n                    for (size s = 0; s < S; s++) {\n                        for (size c = 0; c < C; c++) {\n                            sum += dataIn.get<fp32>(((p + r) * W + (q + s)) * C + c) *\n                                   weightData.get<fp32>(((r * S + s) * C + c) * M + m);\n                        }\n                    }\n                }\n\n                // ReLU activation is part of the layer, as in the Keras Conv2D layers of the model\n                dataOut.get<fp32>((p * Q + q) * M + m) = sum > 0 ? sum : 0;\n            }\n        }\n    }\n}"}, {"key": "lab4", "title": "Lab 4 · 정수 convolution", "path": "cpre487lab4/lab4/framework/src/layers/Convolutional.cpp", "start": 107, "code": "    for (std::size_t oy = 0; oy < outH; oy++) {\n        for (std::size_t ox = 0; ox < outW; ox++) {\n            for (std::size_t oc = 0; oc < outC; oc++) {\n                i32 acc = biases[oc];\n\n                for (std::size_t ky = 0; ky < kH; ky++) {\n                    for (std::size_t kx = 0; kx < kW; kx++) {\n                        for (std::size_t ic = 0; ic < inC; ic++) {\n                            std::size_t inputIdx = (((oy + ky) * inW) + (ox + kx)) * inC + ic;\n                            std::size_t weightIdx = (((ky * kW) + kx) * inC + ic) * outC + oc;\n                            acc += (in[inputIdx] - quant.inZero) * weights[weightIdx];\n                        }\n                    }\n                }\n\n                // Dequantize, then ReLU in the real domain (so the zero point is handled correctly)\n                fp32 y = acc / accScale;\n                if (y < 0) y = 0;"}, {"key": "lab5", "title": "Lab 5 · patch → hardware MAC", "path": "cpre487lab5/sw/framework/src/layers/Convolutional.cpp", "start": 182, "code": "    std::vector<i32> offsets(outC);\n    for (std::size_t oc = 0; oc < outC; oc++) {\n        i32 weightSum = 0;\n        for (std::size_t k = 0; k < groupSize; k++) {\n            kernels[oc * groupSize + k] = weights[k * outC + oc];\n            weightSum += weights[k * outC + oc];\n        }\n        offsets[oc] = biases[oc] - quant.inZero * weightSum;\n    }\n\n    std::vector<i8> patch(groupSize);\n    for (std::size_t oy = 0; oy < outH; oy++) {\n        for (std::size_t ox = 0; ox < outW; ox++) {\n            // Gather the input window once; it is shared by every output channel\n            for (std::size_t ky = 0; ky < kH; ky++) {\n                for (std::size_t kx = 0; kx < kW; kx++) {\n                    for (std::size_t ic = 0; ic < inC; ic++) {\n                        patch[((ky * kW) + kx) * inC + ic] = in[(((oy + ky) * inW) + (ox + kx)) * inC + ic];\n                    }\n                }\n            }\n\n            for (std::size_t oc = 0; oc < outC; oc++) {\n                i32 acc = macGroup(&kernels[oc * groupSize], patch.data(), groupSize, quant.bits) + offsets[oc];"}, {"key": "lab3", "title": "Lab 3 · multiply / accumulate", "path": "cpre487lab3/piped_mac/hdl/piped_mac.vhd", "start": 142, "code": "                        when MUL_STAGE =>\n                            s1_valid   <= s0_valid;\n                            s1_product <= resize(s0_A * s0_B, FourBytes);\n                            s1_bias    <= s0_bias;\n                            s1_user    <= s0_user;\n                            s1_last    <= s0_last;\n                            s1_tid     <= s0_tid;\n\n                        when ADD_STAGE =>\n                            s2_valid <= s1_valid;\n                            s2_last  <= s1_last;\n                            s2_tid   <= s1_tid;\n\n                            if s1_valid = '1' then\n                                if s1_user = '1' then\n                                    s2_sum <= s1_bias;\n                                    if s1_last = '1' then\n                                        acc <= (others => '0');\n                                    else\n                                        acc <= s1_bias;\n                                    end if;\n                                else\n                                    s2_sum <= acc + s1_product;\n                                    if s1_last = '1' then\n                                        acc <= (others => '0');\n                                    else\n                                        acc <= acc + s1_product;\n                                    end if;"}]};
